        FeatureCategoryEntry(name: "Audio", description: "Audio", modelKey: ["camera"]),
        FeatureCategoryEntry(name: "Device", description: "Device", modelKey: ["all"]),
        FeatureCategoryEntry(name: "Doorbell", description: "Doorbell", modelKey: ["camera"]),
        FeatureCategoryEntry(name: "Log", description: "Logging", modelKey: ["camera", "light", "sensor"]),
        FeatureCategoryEntry(name: "Motion", description: "Motion", modelKey: ["camera", "light", "sensor"], hasSensorFeature: ["motion"], isNotProperty: ["isAdoptedByAccessApp", "isThirdPartyCamera"]),
        FeatureCategoryEntry(name: "Nvr", description: "NVR", modelKey: ["camera", "nvr"]),
        FeatureCategoryEntry(name: "SecuritySystem", description: "Security System", modelKey: ["nvr"]),
        FeatureCategoryEntry(name: "Sensor", description: "Sensor", modelKey: ["sensor"]),
